'use client';

import React from 'react';
import { MessageCircle } from 'lucide-react';
import { contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';

export const WhatsAppButton: React.FC = () => {
  const whatsappUrl = createWhatsAppLink(
    contactInfo.defaultWhatsApp,
    'مرحباً NT Media Agency، أود الاستفسار عن باقاتكم وخدماتكم.'
  );

  return (
    <aside aria-label="تواصل فوري" className="fixed bottom-6 left-6 z-50">
      <a
        href={whatsappUrl}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="تواصل عبر واتساب"
        className="flex items-center gap-2.5 bg-neutral-900 text-white px-4 py-3 rounded-full shadow-lg hover:bg-neutral-800 hover:scale-105 active:scale-95 transition-all duration-300 group border border-neutral-700"
      >
        <MessageCircle className="w-5 h-5 text-emerald-400 group-hover:rotate-12 transition-transform duration-300" />
        <span className="text-sm font-medium">تواصل فوري</span>
      </a>
    </aside>
  );
};